insert into notif_templates (key, grp, pref, sms, sms_mode, push, push_private, app, biz_pref, title, body) values
  ('viaje_alt_fin', 'tx', 'cit', true, 'sin_push', true, false, 'cliente', null, '{"es": "Venció la otra salida", "en": "The other departure expired"}', '{"es": "Venció la salida que te propuso {negocio} para el {dia}. No hay reserva.{dinero}", "en": "The departure {negocio} proposed for {dia} expired. No booking.{dinero}"}'),
  ('noche_alt_fin', 'tx', 'cit', true, 'sin_push', true, false, 'cliente', null, '{"es": "Venció la otra hora", "en": "The new time expired"}', '{"es": "Venció la otra hora que te propuso {negocio} para {noche}. No hay reserva.{dev}", "en": "The new time {negocio} proposed for {noche} expired. No booking.{dev}"}'),
  ('fiesta_alt_fin', 'tx', 'cit', true, 'sin_push', true, false, 'cliente', null, '{"es": "Venció la otra hora", "en": "The new time expired"}', '{"es": "Venció la otra hora que te propuso {negocio} para tu fiesta del {dia}. No hay reserva.{dev}", "en": "The new time {negocio} proposed for your party on {dia} expired. No booking.{dev}"}'),
  ('insc_alt_fin', 'tx', 'cit', true, 'sin_push', true, false, 'cliente', null, '{"es": "Venció el otro grupo", "en": "The other group expired"}', '{"es": "Venció el otro grupo que te propuso {negocio}. No hay inscripción.{dev}", "en": "The other group {negocio} proposed expired. No enrollment.{dev}"}'),
  ('insc_fe_alt_fin', 'tx', 'cit', true, 'sin_push', true, false, 'cliente', null, '{"es": "Venció la otra fecha", "en": "The other date expired"}', '{"es": "Venció la otra fecha que te propuso {negocio}. Pide otra cuando quieras.{dev}", "en": "The other date {negocio} proposed expired. Ask for another whenever you want.{dev}"}'),
  ('insc_fen_alt_fin', 'tx', 'cit', true, 'sin_push', true, false, 'cliente', null, '{"es": "Venció la otra fecha", "en": "The other date expired"}', '{"es": "Venció la otra fecha que te propusieron. Mira los detalles en To''Latino.", "en": "The other date they proposed expired. See the details in To''Latino."}'),
  ('vis_alt_fin', 'tx', 'cit', true, 'sin_push', true, false, 'cliente', null, '{"es": "Venció la otra hora", "en": "The other time expired"}', '{"es": "Venció la otra hora que te propuso {negocio} para tu solicitud {num}. No se cobró nada: pide otra hora cuando quieras.", "en": "The other time {negocio} proposed for your request {num} expired. Nothing was charged: request another time whenever you want."}'),
  ('biz_viaje_alt_fin', 'biz', null, false, 'nunca', true, false, 'negocio', 'citas', '{"es": "Venció la otra salida", "en": "The other departure expired"}', '{"es": "{cliente} no respondió a la otra salida de su reserva del {dia} ({servicio}). Se canceló y los asientos quedaron libres.{dinero}", "en": "{cliente} did not answer the other departure for their booking on {dia} ({servicio}). It was cancelled and the seats are free again.{dinero}"}'),
  ('biz_noche_alt_fin', 'biz', null, false, 'nunca', true, false, 'negocio', 'reservas', '{"es": "Venció la otra hora", "en": "The new time expired"}', '{"es": "{cliente} no respondió a la otra hora de su {servicio} de {noche}. Se canceló y el lugar quedó libre.{dinero}", "en": "{cliente} did not answer the new time for their {servicio} on {noche}. It was cancelled and the spot is free again.{dinero}"}'),
  ('biz_fiesta_alt_fin', 'biz', null, false, 'nunca', true, false, 'negocio', 'citas', '{"es": "Venció la otra hora", "en": "The new time expired"}', '{"es": "{cliente} no respondió a la otra hora de la fiesta del {dia}. Se canceló y la fecha quedó libre.{dinero}", "en": "{cliente} did not answer the new time for the party on {dia}. It was cancelled and the date is free again.{dinero}"}'),
  ('biz_insc_alt_fin', 'biz', null, false, 'nunca', true, false, 'negocio', 'citas', '{"es": "Venció el otro grupo", "en": "The other group expired"}', '{"es": "{cliente} no respondió al otro grupo de {servicio}. La inscripción se canceló y el cupo quedó libre.{dinero}", "en": "{cliente} did not answer the other group for {servicio}. The enrollment was cancelled and the spot is free again.{dinero}"}'),
  ('biz_vis_alt_fin', 'biz', null, false, 'nunca', true, false, 'negocio', 'citas', '{"es": "Venció la otra hora", "en": "The other time expired"}', '{"es": "{cliente} no respondió a la otra hora de la solicitud {num} ({cuando}). Se canceló y la hora quedó libre.", "en": "{cliente} did not answer the other time for request {num} ({cuando}). It was cancelled and the time is free again."}')
